package com.digitalhealth.controller;
import com.digitalhealth.dto.DashboardDTO; import com.digitalhealth.model.*; import com.digitalhealth.repository.*; import com.digitalhealth.security.*; import com.digitalhealth.service.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/dashboard") @CrossOrigin(originPatterns={"http://localhost:*","http://127.0.0.1:*"}) public class DashboardController {private final AccessService access;private final WorkerRepository workers;private final UserAccountRepository users;private final AppointmentRepository appointments;private final HealthcareCenterRepository centers;private final WorkerService workerService;private final HealthProfileService profiles;private final AppointmentService appointmentService;private final NotificationService notificationService;private final HealthRecordService recordService;public DashboardController(AccessService a,WorkerRepository w,UserAccountRepository u,AppointmentRepository ap,HealthcareCenterRepository c,WorkerService ws,HealthProfileService p,AppointmentService as,NotificationService ns,HealthRecordService rs){access=a;workers=w;users=u;appointments=ap;centers=c;workerService=ws;profiles=p;appointmentService=as;notificationService=ns;recordService=rs;}@GetMapping public DashboardDTO get(){var u=access.current();var d=new DashboardDTO();if(u.role()==Role.WORKER){Long id=u.workerId();access.workerOrAdmin(id);d.worker=workerService.getById(id);try{d.profile=profiles.get(id);}catch(Exception ignored){}d.recentRecords=recordService.list(id,RecordType.CONSULTATION);d.appointments=appointmentService.list(id);d.notifications=notificationService.list(id);return d;}if(u.role()==Role.ADMIN){d.counts.put("workers",workers.count());d.counts.put("doctors",users.countByRole(Role.DOCTOR));d.counts.put("providers",users.countByRole(Role.HEALTHCARE_PROVIDER));d.counts.put("centers",centers.count());d.counts.put("appointments",appointments.count());return d;}access.providerOrAdmin();d.counts.put("appointments",appointments.count());d.counts.put("workers",workers.count());return d;}}
